WITH metrics AS (SELECT *, MIN(rating) OVER (PARTITION BY city) city_min_rating, ROW_NUMBER() OVER (PARTITION BY country, city ORDER BY rating, id) seq_no, AVG(rating) OVER (PARTITION BY country ORDER BY rating, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) rating_avg_6, NTILE(5) OVER w_ordered rating_bucket, PERCENT_RANK() OVER (ORDER BY rating DESC NULLS FIRST) rating_percent_rank FROM suppliers WHERE supplier_name LIKE '%EuroGood%' WINDOW w_ordered AS (PARTITION BY country ORDER BY rating, id)) SELECT id, city, rating, city_min_rating, seq_no, rating_avg_6, rating_bucket, rating_percent_rank FROM metrics ORDER BY rating NULLS FIRST;
